#!/usr/bin/env python3
from __future__ import annotations

import argparse
import json
import re
import sys
from datetime import datetime
from pathlib import Path
from typing import Any

_TIMESTAMP_RE = re.compile(r"\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ")


def _load_json(path: Path) -> dict[str, Any]:
    with path.open("r", encoding="utf-8") as handle:
        value = json.load(handle)
    if not isinstance(value, dict):
        raise ValueError(f"{path} must contain a JSON object")
    return value


def _load_stdin() -> dict[str, Any]:
    try:
        value = json.load(sys.stdin)
    except json.JSONDecodeError as exc:
        raise ValueError(f"stdin must be one JSON object: {exc}") from exc
    if not isinstance(value, dict):
        raise ValueError("stdin must be one JSON object")
    return value


def _validate_view(view: dict[str, Any]) -> dict[str, Any]:
    if view.get("kind") != "ListingView":
        raise ValueError("--view must reference a ListingView resource")
    spec = view.get("spec")
    if not isinstance(spec, dict):
        raise ValueError("ListingView must contain a spec object")
    if spec.get("filterStatus") != "Open":
        raise ValueError("unsupported ListingView filterStatus")
    if spec.get("sortFields") != ["openedAt", "id"]:
        raise ValueError("unsupported ListingView sortFields")
    if spec.get("sortOrder") != "ascending":
        raise ValueError("unsupported ListingView sortOrder")
    if spec.get("outputFormat") != "json-stdout":
        raise ValueError("unsupported ListingView outputFormat")
    return spec


def _validate_row(row: Any) -> dict[str, Any]:
    if not isinstance(row, dict):
        raise ValueError("each item must be a JSON object")
    item_id = row.get("id")
    if not isinstance(item_id, str) or not item_id:
        raise ValueError("each item must have a non-empty string id")
    opened_at = row.get("openedAt")
    if not isinstance(opened_at, str) or not _TIMESTAMP_RE.fullmatch(opened_at):
        raise ValueError(f"item {item_id!r} must have a canonical UTC openedAt timestamp")
    try:
        datetime.strptime(opened_at, "%Y-%m-%dT%H:%M:%SZ")
    except ValueError as exc:
        raise ValueError(f"item {item_id!r} must have a valid UTC openedAt timestamp") from exc
    return row


def project_items(view: dict[str, Any], payload: dict[str, Any]) -> dict[str, list[dict[str, Any]]]:
    spec = _validate_view(view)
    items = payload.get("items")
    if not isinstance(items, list):
        raise ValueError("stdin object must contain an items array")

    selected: list[dict[str, Any]] = []
    seen_ids: set[str] = set()
    for raw_row in items:
        row = _validate_row(raw_row)
        if row.get("status") == spec["filterStatus"]:
            item_id = row["id"]
            if item_id in seen_ids:
                raise ValueError("selected rows must have unique stable ids")
            seen_ids.add(item_id)
            selected.append(row)

    selected.sort(key=lambda row: (row["openedAt"], row["id"]))
    return {"items": selected}


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="List open dispatch listings as JSON.")
    parser.add_argument("--view", required=True, help="Path to the ListingView JSON resource.")
    args = parser.parse_args(argv)

    try:
        view = _load_json(Path(args.view))
        payload = _load_stdin()
        result = project_items(view, payload)
    except Exception as exc:
        print(str(exc), file=sys.stderr)
        return 1

    json.dump(result, sys.stdout, separators=(",", ":"))
    sys.stdout.write("\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
